<section class="restaurant-pos" data-pos-root data-pos-version="<?= (int)$cart['account']['version'] ?>">
<div class="restaurant-pos-catalog restaurant-panel"><div class="restaurant-pos-catalog-head"><div><p class="eyebrow">CARTA</p><h2>Selecciona los productos</h2></div><a class="button" href="index.php">← Mesas</a></div>
<label class="restaurant-pos-search"><span class="visually-hidden">Buscar producto</span><input type="search" data-pos-search placeholder="Buscar producto…" autocomplete="off"></label>
<?php require __DIR__.'/categories.php'; ?>
<div class="restaurant-pos-products"><?php foreach($page['products'] as $product): ?><form method="post" data-pos-command data-pos-product data-pos-name="<?= $h(mb_strtolower($product['name'])) ?>" data-pos-category-id="<?= (int)$product['category_id'] ?>"><?php restaurantPosFields($cart,'pos_add'); ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><button type="submit" <?= !$editable||!$product['available']?'disabled':'' ?>><span class="restaurant-pos-product-icon" aria-hidden="true"><?= $h(mb_substr($product['name'],0,1)) ?></span><strong><?= $h($product['name']) ?></strong><span><?= $product['available']?$h($product['display_price'].' '.$cart['currency']):'Requiere tasa' ?></span><?php if($editable): ?><b aria-hidden="true">＋</b><?php endif; ?></button></form><?php endforeach; ?></div>
<?php if(!$page['products']): ?><p class="restaurant-empty"><?= empty($page['restaurantCategoryIds'])?'Marca «Es para restaurante» en las categorías principales de Inventario para mostrar sus productos aquí.':'No hay productos habilitados para venta en las categorías de restaurante.' ?></p><?php endif; ?><p class="restaurant-empty" data-pos-no-results hidden>No se encontraron productos.</p>
</div>
<aside class="restaurant-panel restaurant-pos-ticket" aria-label="Pedido de la mesa"><p class="restaurant-error" data-pos-error role="alert" hidden></p><p class="restaurant-pos-saving" data-pos-saving role="status" hidden>Guardando…</p><div data-pos-cart><?php require __DIR__.'/cart.php'; ?></div></aside>
<?php if(isset($page['clients'])&&$cart['account']['status']==='open'): ?>
<dialog class="restaurant-pos-dialog" data-pos-checkout-dialog><form method="post" data-pos-command data-pos-checkout-form><?php restaurantPosFields($cart,'pos_checkout'); ?><div class="restaurant-pos-catalog-head"><h2>Facturar y cobrar</h2><button type="button" class="button" data-pos-close-checkout aria-label="Cerrar">×</button></div><p>Confirma el cliente y dónde recibes el pago. Se emitirá la factura y se registrará el cobro completo.</p>
<div class="restaurant-fields"><?php foreach(['customer_id'=>['Cliente',$page['clients']],'method_id'=>['Medio de pago',$page['methods']],'account_id'=>['Caja o banco',$page['cashAccounts']],'location_id'=>['Ubicación del inventario',$page['locations']]] as $field=>[$label,$options]): ?><label><?= $h($label) ?><select name="<?= $h($field) ?>" required data-pos-preference="<?= $h($field) ?>"><?php if(count($options)!==1): ?><option value="">Selecciona…</option><?php endif; ?><?php foreach($options as $option): ?><option value="<?= (int)$option['id'] ?>"><?= $h($option['name']) ?></option><?php endforeach; ?></select></label><?php endforeach; ?></div>
<p class="restaurant-pos-dialog-error" data-pos-dialog-error role="alert" hidden></p><button class="button button-primary" type="submit">Confirmar factura y cobro</button><small>La mesa quedará pendiente de limpieza. No se generan documentos duplicados al reintentar.</small></form></dialog>
<?php endif; ?></section>
